function renderGenerator(){const i=genIdentity(),hasRec=Object.keys(bundle.records).length>0,codes=memberCodes(i),st=Object.fromEntries(subjects.map(s=>[s,lkStatus(s)])),chk=crossChecks(),ch=chainData();
 const stepDone=[!identityErrors(i).length,subjects.every(s=>st[s].k!=='belum'),subjects.every(s=>st[s].k==='lengkap')&&chk.every(c=>c[0]===true),hasRec,TEXTS.every(k=>bundle[k].trim()),!bundleErrors().length];
 const steps=['Identitas','Unggah 4 LK','Pemeriksaan','Integrasi','Refleksi','Generate'];
 $('content').innerHTML=`<nav class="gsteps" aria-label="Langkah generator">${steps.map((s,n)=>`<a href="#g${n+1}" class="${stepDone[n]?'done':''}"><b>${n+1}</b>${s}</a>`).join('')}</nav>
<section class="panel" id="g1"><span class="eyebrow">LANGKAH 1 · PEKAN 6 · P14</span><h2>Identitas kelompok dan kasus</h2>${hasRec?`<p class="check">Diambil dari LK yang diunggah: <b>${E(i.group_id)}</b> · Kelas ${E(i.class_name)} · ${E(caseName(i.case_id))} · Anggota ${E(codes.join(', '))}. LK dari kelompok lain akan ditolak.</p>`:`<p class="small">Isi sama persis dengan identitas pada LK. LK yang identitasnya berbeda akan ditolak.</p><div class="grid"><label>Kode kelompok<input id="g_group_id" maxlength="30" value="${E(i.group_id)}"></label><label>Kelas<input id="g_class_name" maxlength="40" value="${E(i.class_name)}"></label><label>Kasus kelompok<select id="g_case_id"><option value="">— pilih kasus —</option>${D.cases.map(c=>`<option value="${c[0]}" ${c[0]===i.case_id?'selected':''}>${E(c[1])}</option>`).join('')}</select></label><label>Kode anggota<input id="g_members" maxlength="200" value="${E(i.members)}"></label></div>`}${caseCard(i.case_id)}
<div class="grid"><label>Judul karya (sampul laporan)<input id="g_judul" data-meta="judul" maxlength="120" placeholder="Contoh: Foto OSIS Aman Dibagikan" value="${E(bundle.judul)}"></label><label>Nama sekolah<input id="g_sekolah" data-meta="sekolah" maxlength="120" value="${E(bundle.sekolah)}"></label></div>
${codes.length?`<details><summary>Nama tampilan anggota (opsional)</summary><p class="small">Kosongkan bila belum ada izin. Laporan memakai kode anggota bila nama kosong.</p><div class="grid">${codes.map(k=>`<label>${E(k)}<input data-name="${E(k)}" maxlength="60" value="${E(bundle.names[k]||'')}"></label>`).join('')}</div></details>`:''}</section>
<section class="panel" id="g2"><span class="eyebrow">LANGKAH 2</span><h2>Unggah empat LK</h2><p>Unggah berkas .json dari tombol simpan setiap LK. Sistem mengenali mapel dari isi berkas. Setiap kartu dapat diganti tanpa mengulang kartu lain.</p><label class="upload secondary">Unggah beberapa LK atau cadangan<input id="uploadmany" type="file" multiple accept=".json,application/json"></label>
<div class="cards lkcards">${subjects.map(id=>{const r=bundle.records[id],s=st[id];return `<article class="lkcard s-${s.k}" data-sub="${id}"><h3>LK ${E(D.defs[id].name)}</h3><p class="badge">${{belum:'Belum diunggah',ditolak:'Ditolak',draf:'Draf',lengkap:'Lengkap'}[s.k]}</p>${s.k!=='belum'?`<p class="small">${E(s.t)}</p>`:''}${r?`<p class="small">${E(r.identity.group_id)} · disimpan ${E(String(r.completed_at||'').slice(0,16).replace('T',' '))}</p>`:''}${rejected[id]?`<p class="small rej">${E(rejected[id])}${r?' LK sebelumnya tetap dipakai.':''}</p>`:''}<div class="actions"><label class="upload secondary">${r?'Ganti':'Unggah'}<input type="file" data-sub="${id}" accept=".json,application/json"></label>${r?`<button class="secondary" data-remove="${id}">Lepaskan</button>`:''}</div></article>`}).join('')}</div></section>
<section class="panel" id="g3"><span class="eyebrow">LANGKAH 3</span><h2>Pemeriksaan kelengkapan dan kesesuaian</h2>${chk.length?`<ul class="checks">${chk.map(([ok,t])=>`<li class="${ok===true?'ok':ok==='warn'?'warn':'no'}">${E(t)}</li>`).join('')}</ul>`:'<p class="small">Unggah LK untuk mulai memeriksa.</p>'}<p class="small">Tanda kuning bukan penolakan; tuliskan penjelasannya pada kesimpulan atau risiko tersisa.</p></section>
<section class="panel" id="g4"><span class="eyebrow">LANGKAH 4</span><h2>Integrasi temuan lintas mapel</h2><div class="gchain"><div><span>MAT</span><b>Prediksi model</b>${E(ch.pred?ch.pred.join(' > '):'belum ada')}</div><div><span>IPA</span><b>Data nyata</b>${E(ch.sp.length?ch.sp.map(s=>s.k+' '+dec(s.mean)+' m').join(' · '):'belum ada')}${ch.cocok!==null?`<small>${ch.cocok}/${ch.sp.length} urutan sama dengan prediksi</small>`:''}</div><div><span>KKA</span><b>Keputusan desain</b>${E(ch.fin?'Alternatif '+ch.fin:'belum ada')}${ch.t?`<small>uji final K2 ${ch.t.k2}/${ch.t.n}</small>`:''}</div><div><span>IPS</span><b>Protokol</b>${E(ch.rec.length?ch.rec.length+' rekomendasi berbukti':'belum ada')}</div></div><p class="small">Rantai ini menjadi alur cerita laporan: prediksi diuji dengan data, data menentukan desain, desain menjadi protokol.</p></section>
<section class="panel" id="g5"><span class="eyebrow">LANGKAH 5</span><h2>Kesimpulan, refleksi, dan dokumentasi</h2><div class="actions"><button class="secondary" id="kerangka" type="button">Masukkan kerangka kesimpulan dari bukti</button></div>${field('final','conclusion','Apa tindakan yang dipilih? Hubungkan bukti IPS, MAT, KKA, dan IPA dengan asal datanya.',bundle.conclusion,6)}${field('final','limits','Apa risiko tersisa dan keterbatasan solusi? Apa perubahan setelah pengujian?',bundle.limits,3)}${field('final','protocol','Protokol untuk pengguna: tulis tiga rekomendasi singkat, penerima, dan dasar buktinya.',bundle.protocol,5)}${field('final','ujibaca','Uji baca protokol: siapa (peran, bukan nama) minimal dua pembaca di luar kelompok, apa yang mereka pahami, dan satu perbaikan yang kalian lakukan.',bundle.ujibaca,3)}${field('final','refleksi','Refleksi kelompok: apa yang paling kalian pelajari, apa yang akan kalian lakukan berbeda, dan bagaimana kerja sama kelompok?',bundle.refleksi,4)}
<h3>Galeri dokumentasi (maksimal ${PHOTO_MAX} foto)</h3><p class="small">Foto diperkecil dan disalin ulang sehingga GPS dan metadata lain tidak ikut. Hindari wajah atau nama murid tanpa izin.</p><label class="upload secondary">Tambah foto<input id="photofile" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><div class="gphotos">${bundle.photos.map((p,n)=>`<figure><img src="${E(p.src)}" alt="${E(p.cap||'Foto dokumentasi '+(n+1))}"><input data-cap="${n}" maxlength="160" placeholder="Keterangan foto" value="${E(p.cap)}" aria-label="Keterangan foto ${n+1}"><button class="secondary" data-delphoto="${n}" type="button">Hapus</button></figure>`).join('')}</div></section>
<section class="panel" id="g6"><span class="eyebrow">LANGKAH 6</span><h2>Pratinjau dan unduh</h2><p id="genstatus"></p><div class="actions"><button id="preview" type="button">Pratinjau laporan interaktif</button><button id="genhtml" type="button">Generate Laporan Interaktif</button><button id="finalpdf" type="button">Unduh PDF final</button><button id="finalzip" type="button">Unduh paket ZIP</button><button class="secondary" id="backup" type="button">Simpan cadangan JSON</button></div><p class="small">Laporan interaktif berupa satu berkas HTML: dapat dibuka tanpa internet di browser mana pun dan memiliki Mode Presentasi (tombol di sampul, atau tekan P). Cadangan JSON dapat diunggah kembali untuk melanjutkan pekerjaan.</p></section>
<section class="panel" id="previewarea" hidden></section>`;
 const setId=()=>{const g={group_id:$('g_group_id').value.trim(),class_name:$('g_class_name').value.trim(),case_id:$('g_case_id').value,members:$('g_members').value.trim()};bundle.identity=g;persistBundle();};
 if(!hasRec){for(const k of ['group_id','class_name','members'])$('g_'+k).onchange=()=>{setId();renderGenerator()};$('g_case_id').onchange=()=>{setId();renderGenerator()};}
 document.querySelectorAll('[data-meta]').forEach(el=>el.oninput=()=>{bundle[el.dataset.meta]=el.value;persistBundle()});
 document.querySelectorAll('[data-name]').forEach(el=>el.oninput=()=>{const v=el.value.trim();if(v)bundle.names[el.dataset.name]=el.value;else delete bundle.names[el.dataset.name];persistBundle()});
 $('uploadmany').onchange=e=>safe(()=>importFiles([...e.target.files]));
 document.querySelectorAll('input[type=file][data-sub]').forEach(el=>el.onchange=e=>safe(()=>importFiles([...e.target.files],el.dataset.sub)));
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(confirm('Lepaskan LK dari gabungan? File asli tetap tersimpan.')){delete bundle.records[b.dataset.remove];delete rejected[b.dataset.remove];persistBundle();renderGenerator();}});
 document.querySelectorAll('[data-answer]').forEach(el=>el.oninput=()=>{bundle[el.dataset.answer]=el.value;persistBundle();genStatus()});
 $('kerangka').onclick=()=>{const t=$('final_conclusion');if(t.value.trim()&&!confirm('Kesimpulan sudah berisi. Tambahkan kerangka di bawahnya?'))return;t.value=(t.value.trim()?t.value.trim()+'\n\n':'')+kerangka();bundle.conclusion=t.value;persistBundle();genStatus();t.focus();notify('Kerangka dimasukkan. Ganti setiap tanda … dengan penjelasan kelompok.');};
 $('photofile').onchange=e=>safe(async()=>{const fs=[...e.target.files],msgs=[];for(const f of fs){if(bundle.photos.length>=PHOTO_MAX){msgs.push(f.name+': galeri penuh ('+PHOTO_MAX+' foto)');continue;}try{bundle.photos.push({src:await shrinkPhoto(f),cap:''});msgs.push(f.name+': ditambahkan')}catch(err){msgs.push(err.message)}}persistBundle();renderGenerator();notify(msgs.join(' | '),msgs.some(x=>!x.endsWith('ditambahkan')));});
 document.querySelectorAll('[data-cap]').forEach(el=>el.oninput=()=>{bundle.photos[+el.dataset.cap].cap=el.value;persistBundle()});
 document.querySelectorAll('[data-delphoto]').forEach(b=>b.onclick=()=>{bundle.photos.splice(+b.dataset.delphoto,1);persistBundle();renderGenerator();});
 $('final_protocol').maxLength=1800;
 $('preview').onclick=()=>safe(async()=>{const el=$('previewarea');el.hidden=false;el.innerHTML=`<h2>Pratinjau laporan interaktif</h2><p class="small">${E(bundleErrors().length?'DRAF — bagian yang belum lengkap ditandai di laporan.':'Bagian wajib lengkap; periksa isi bersama guru.')} Pratinjau ini sama dengan berkas yang diunduh.</p>`;const f=document.createElement('iframe');f.className='gpreview';f.title='Pratinjau laporan interaktif';f.setAttribute('sandbox','allow-scripts');f.setAttribute('allowfullscreen','');f.srcdoc=reportHTML();el.append(f);el.scrollIntoView({behavior:'smooth'});});
 $('genhtml').onclick=()=>safe(async()=>{if(!hasRec)throw Error('Unggah minimal satu LK terlebih dahulu.');const e=bundleErrors();download(reportHTML(),`Laporan_Interaktif_${slug(i.group_id)}${e.length?'_DRAF':''}.html`,'text/html');notify(e.length?'Laporan DRAF diunduh. Lengkapi: '+e.join(' · '):'Laporan interaktif diunduh. Buka berkasnya dengan browser; tidak perlu internet.',e.length>0);});
 $('backup').onclick=()=>download(JSON.stringify({app_id:APP,schema_version:19,kind:'gabungan',saved_at:new Date().toISOString(),bundle},null,2),`Gabungan_${slug(i.group_id)}.json`);
 $('finalpdf').onclick=()=>safe(async()=>{checkFinal();download(await finalPDF(),`Laporan_${slug(i.group_id)}.pdf`)});
 $('finalzip').onclick=()=>safe(async()=>{checkFinal();const files=[{nama:'Laporan_Interaktif.html',isi:reportHTML()},{nama:'Laporan_Proyek.pdf',isi:new Uint8Array(await (await finalPDF()).arrayBuffer())},{nama:'Gabungan.json',isi:JSON.stringify({app_id:APP,schema_version:19,kind:'gabungan',bundle},null,2)}];for(const [s,r]of Object.entries(bundle.records)){files.push({nama:`LK_${s.toUpperCase()}.json`,isi:JSON.stringify(r,null,2)});for(const k of attKinds)if(r.attachments[k])files.push({nama:`data_${s}_${k}.csv`,isi:r.attachments[k].text});if(r.attachments.code)files.push({nama:'Program_Kelompok.py',isi:r.attachments.code});if(r.attachments.notebook)files.push({nama:'Notebook_Kelompok.ipynb',isi:r.attachments.notebook.text});}download(zipLK(files,'application/zip'),`Karya_${slug(i.group_id)}.zip`);notify('Paket karya diunduh. Kumpulkan melalui saluran yang ditentukan guru.');});genStatus();}
function genStatus(){const e=bundleErrors();$('genstatus').textContent=e.length?'Belum siap final: '+e.join(' · '):'Empat LK, kesimpulan, dan refleksi terisi. Periksa isi, lalu unduh karya.';$('finalpdf').disabled=$('finalzip').disabled=e.length>0;$('genhtml').disabled=!Object.keys(bundle.records).length;$('genhtml').textContent=e.length?'Generate Laporan Interaktif (draf)':'Generate Laporan Interaktif';}
function checkFinal(){const err=bundleErrors();if(err.length)throw Error(err.join(' · '));}
async function finalPDF(){const i=genIdentity(),intro=baseModel(bundle.judul.trim()||'Laporan Kit Berbagi Foto Aman',i);if(bundle.sekolah.trim())intro.push({t:'jawab',x:'Sekolah: '+bundle.sekolah.trim()});intro.push({t:'h',x:'Kesimpulan integrasi'},{t:'jawab',x:bundle.conclusion},{t:'h',x:'Risiko tersisa dan perubahan'},{t:'jawab',x:bundle.limits},{t:'h',x:'Refleksi kelompok'},{t:'jawab',x:bundle.refleksi});const prot=baseModel('Protokol Berbagi Foto',i);prot.push({t:'jawab',x:bundle.protocol},{t:'h',x:'Uji baca protokol'},{t:'jawab',x:bundle.ujibaca});const models=[intro,prot];for(const id of subjects)models.push(await modelRecord(bundle.records[id]));if(bundle.photos.length){const g=baseModel('Dokumentasi Proyek',i);for(const p of bundle.photos)g.push({t:'img',src:p.src},{t:'jawab',x:p.cap||'(tanpa keterangan)'});models.push(g);}return pdfDariModel(models);}
async function safe(fn){try{await fn()}catch(e){notify(e.message||String(e),true)}}
